import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.CSxHcPWC.js";const m=JSON.parse('{"title":"🤝 Contributing to WealthFam","description":"","frontmatter":{},"headers":[],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md"}'),r={name:"CONTRIBUTING.md"};function n(s,e,l,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="🤝-contributing-to-wealthfam" tabindex="-1">🤝 Contributing to WealthFam <a class="header-anchor" href="#🤝-contributing-to-wealthfam" aria-label="Permalink to &quot;🤝 Contributing to WealthFam&quot;">​</a></h1><p>Welcome to the WealthFam Engineering Hub. We follow a &quot;Precision First&quot; engineering philosophy—every commit should be accurate, every feature should be idempotent, and every bug should be documented.</p><hr><h2 id="🏗️-core-contribution-areas" tabindex="-1">🏗️ Core Contribution Areas <a class="header-anchor" href="#🏗️-core-contribution-areas" aria-label="Permalink to &quot;🏗️ Core Contribution Areas&quot;">​</a></h2><h3 id="_1-ingestion-microservice-parser" tabindex="-1">1. Ingestion Microservice (Parser) <a class="header-anchor" href="#_1-ingestion-microservice-parser" aria-label="Permalink to &quot;1. Ingestion Microservice (Parser)&quot;">​</a></h3><p>The <strong>Parser</strong> is the gateway for all Precision data. We are always looking for new regex templates for international and regional banks.</p><ul><li><strong>Location</strong>: <code>parser/core/templates/</code></li><li><strong>Standard</strong>: Follow the existing YAML structure. Each template MUST include test cases for: <ul><li>Successful parsing of debit/credit.</li><li>Identification of account masks.</li><li>Balance discovery (where available).</li></ul></li></ul><h3 id="_2-mobile-native-widgets-flutter" tabindex="-1">2. Mobile Native Widgets (Flutter) <a class="header-anchor" href="#_2-mobile-native-widgets-flutter" aria-label="Permalink to &quot;2. Mobile Native Widgets (Flutter)&quot;">​</a></h3><p>WealthFam Mobile uses a minimalist, high-performance Material 3 design system.</p><ul><li><strong>Location</strong>: <code>mobile_app/lib/widgets/</code></li><li><strong>Guidelines</strong>: Use the built-in <code>PrecisionCard</code> and <code>NeonLabel</code> components. Avoid external styling libraries.</li></ul><h3 id="_3-backend-analytical-engines-fastapi" tabindex="-1">3. Backend Analytical Engines (FastAPI) <a class="header-anchor" href="#_3-backend-analytical-engines-fastapi" aria-label="Permalink to &quot;3. Backend Analytical Engines (FastAPI)&quot;">​</a></h3><p>The backend handles heavy lifting (XIRR, Portfolio rebalancing, AI Triage).</p><ul><li><strong>Location</strong>: <code>backend/app/services/</code></li><li><strong>Requirement</strong>: Use Type Hints throughout. All SQL queries must be optimized for DuckDB’s columnar architecture.</li></ul><hr><h2 id="🛠️-development-standards" tabindex="-1">🛠️ Development Standards <a class="header-anchor" href="#🛠️-development-standards" aria-label="Permalink to &quot;🛠️ Development Standards&quot;">​</a></h2><h3 id="🧬-commit-message-standards" tabindex="-1">🧬 Commit Message Standards <a class="header-anchor" href="#🧬-commit-message-standards" aria-label="Permalink to &quot;🧬 Commit Message Standards&quot;">​</a></h3><p>We use a Precision commit standard for easy auditing:</p><ul><li><code>feat(scope): ...</code> — New functional behavior.</li><li><code>fix(scope): ...</code> — Bug fix (always include the error hash if possible).</li><li><code>infra(scope): ...</code> — Changes to Docker or deployment scripts.</li><li><code>docs(scope): ...</code> — Documentation updates.</li></ul><h3 id="🧪-quality-assurance" tabindex="-1">🧪 Quality Assurance <a class="header-anchor" href="#🧪-quality-assurance" aria-label="Permalink to &quot;🧪 Quality Assurance&quot;">​</a></h3><ol><li><strong>Linting</strong>: Run <code>flake8</code> or <code>eslint</code> before pushing.</li><li><strong>Schema Integrity</strong>: If modifying models, provide a migration patch in <code>backend/app/core/migrations/</code>.</li><li><strong>Idempotency Check</strong>: Ensure your operations (especially in the Parser) can be run safely multiple times.</li></ol><hr><h2 id="📝-the-rfc-process" tabindex="-1">📝 The RFC Process <a class="header-anchor" href="#📝-the-rfc-process" aria-label="Permalink to &quot;📝 The RFC Process&quot;">​</a></h2><p>Major architectural shifts require a <strong>Request for Comments</strong>. Reference the <a href="./Management/RFC_PROCESS.html">RFC Process</a> before starting significant refactors.</p><hr><div align="center"> *Accuracy Above All · Zero Manual Entry · Precision Integrity* </div>',25)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};

